    /// <summary>
    /// The <c>"skip"</c> sentinel a <see cref="ForEachChildRecursively"/> callback returns to stop the walk
    /// from descending into a node or an array.
    /// </summary>
    /// <remarks>
    /// PORT-NOTE: TS compares the callback result against the string literal <c>"skip"</c>. A C#
    /// <c>string</c> would be indistinguishable from a legitimate result, so the sentinel is the singleton of
    /// a private marker type: it can only be produced by referring to this field.
    /// </remarks>
    public static readonly object Skip = SkipMarker.Instance;

    /// <summary>
    /// Walks the tree under <paramref name="rootNode"/> depth-first in pre-order without using the call stack,
    /// calling <paramref name="cbNode"/>/<paramref name="cbNodes"/> with each node/array and its parent.
    /// Returns the first non-<see cref="Skip"/> truthy result, or <c>null</c>.
    /// </summary>
    public static object? ForEachChildRecursively(Node rootNode, Func<Node, Node, object?> cbNode, Func<INodeArray<INode>, Node, object?>? cbNodes = null)
    {
        var queue = GatherPossibleChildren(rootNode);
        var parents = new List<Node>();
        while (parents.Count < queue.Count)
        {
            parents.Add(rootNode);
        }

        while (queue.Count != 0)
        {
            var current = queue[^1];
            var parent = parents[^1];
            queue.RemoveAt(queue.Count - 1);
            parents.RemoveAt(parents.Count - 1);

            if (current is INodeArray<INode> nodes)
            {
                if (cbNodes is not null)
                {
                    var result = cbNodes(nodes, parent);
                    if (Js.IsTruthy(result))
                    {
                        if (ReferenceEquals(result, Skip)) continue;
                        return result;
                    }
                }

                // Reversed, so that popping visits the elements in order.
                for (var i = nodes.Count - 1; i >= 0; --i)
                {
                    queue.Add(nodes[i]);
                    parents.Add(parent);
                }
            }
            else
            {
                var node = (Node)current;
                var result = cbNode(node, parent);
                if (Js.IsTruthy(result))
                {
                    if (ReferenceEquals(result, Skip)) continue;
                    return result;
                }

                if (node.Kind >= SyntaxKind.FirstNode)
                {
                    foreach (var child in GatherPossibleChildren(node))
                    {
                        queue.Add(child);
                        parents.Add(node);
                    }
                }
            }
        }

        return null;
    }

    /// <summary>
    /// The children of <paramref name="node"/> as work items — nodes and arrays mixed. TS prepends each one
    /// (<c>unshift</c>) so that the walk's <c>pop</c> restores the source order.
    /// </summary>
    private static List<object> GatherPossibleChildren(Node node)
    {
        var children = new List<object>();
        ForEachChild(node, AddNode, AddNodes);
        return children;

        // Both callbacks return null (TS returns undefined), so the chain always reaches every child.
        object? AddNode(Node child)
        {
            children.Insert(0, child);
            return null;
        }

        object? AddNodes(INodeArray<INode> nodes)
        {
            children.Insert(0, nodes);
            return null;
        }
    }

    /// <summary>One child: TS's <c>visitNode(cbNode, node)</c> — skip when the member is missing, else call.</summary>
    /// <remarks>
    /// PORT-NOTE: the guard is <c>node is null</c> rather than <c>Js.IsTruthy(node)</c>; for a reference type
    /// the two answer the same question, and only the pattern tells the compiler that the cast below is safe.
    /// </remarks>
    private static T? VisitNode<T>(INode? node, Func<Node, T?> cbNode)
        => node is null ? default : cbNode((Node)node);

    /// <summary>An embedded array: TS's <c>visitNodes(cbNode, cbNodes, nodes)</c>.</summary>
    /// <remarks>
    /// With a <paramref name="cbNodes"/> the array itself is handed over — no copy, no flattening. Without
    /// one the elements are visited with <paramref name="cbNode"/> until a truthy result appears, which is the
    /// fallback <c>gatherPossibleChildren</c> depends on (it passes the same callback in both positions).
    /// PORT-NOTE: again <c>nodes is null</c> rather than <c>Js.IsTruthy(nodes)</c> — same answer, but it narrows.
    /// </remarks>
    private static T? VisitNodes<T>(INodeArray<INode>? nodes, Func<Node, T?> cbNode, Func<INodeArray<INode>, T?>? cbNodes)
    {
        if (nodes is null) return default;
        if (cbNodes is not null) return cbNodes(nodes);
        foreach (var node in nodes)
        {
            var result = cbNode((Node)node);
            if (Js.IsTruthy(result)) return result;
        }

        return default;
    }

    /// <summary>
    /// An array visited element-wise, never through <c>cbNodes</c>: core.ts's <c>forEach(array, cbNode)</c>,
    /// which two JSDoc visitors use instead of <c>visitNodes</c>.
    /// </summary>
    private static T? VisitElements<T>(IEnumerable<INode>? items, Func<Node, T?> cbNode)
    {
        if (items is null) return default;
        foreach (var item in items)
        {
            var result = cbNode((Node)item);
            if (Js.IsTruthy(result)) return result;
        }

        return default;
    }

    private sealed class SkipMarker
    {
        private SkipMarker()
        {
        }

        public static readonly SkipMarker Instance = new();
    }

