            var result = VisitNodes(commentNodes, cbNode, cbNodes);
            if (Js.IsTruthy(result)) return result;
        }
        return default;
    }

    /// <summary>Child visitor for <see cref="SyntaxKind.PartiallyEmittedExpression"/> — TS's <c>forEachChildInPartiallyEmittedExpression</c> over <c>PartiallyEmittedExpression</c>.</summary>
    // ported from: src/compiler/parser.ts:1135 (forEachChildInPartiallyEmittedExpression → forEachChildInPartiallyEmittedExpression)
    private static T? ForEachChildInPartiallyEmittedExpression<T>(Node node, Func<Node, T?> cbNode, Func<INodeArray<INode>, T?>? cbNodes)
    {
        var n = (PartiallyEmittedExpression)node;

        {
            var result = VisitNode(n.Expression, cbNode);
            if (Js.IsTruthy(result)) return result;
        }
        return default;
    }

}
